package com.jarvis.ai;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.ImageFormat;import android.hardware.camera2.*;import android.media.*;import android.os.*;import java.nio.*;import java.util.*;
public final class CameraController{CameraDevice cam;ImageReader reader;HandlerThread t;Handler h;public interface Callback{void done(byte[] b);}public void capture(Activity a,Callback cb){if(a.checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){a.requestPermissions(new String[]{Manifest.permission.CAMERA},42);return;}try{t=new HandlerThread("jarvis-camera");t.start();h=new Handler(t.getLooper());reader=ImageReader.newInstance(1280,720,ImageFormat.JPEG,2);reader.setOnImageAvailableListener(x->{Image im=null;try{im=x.acquireLatestImage();if(im==null)return;ByteBuffer b=im.getPlanes()[0].getBuffer();byte[] d=new byte[b.remaining()];b.get(d);cb.done(d);}finally{if(im!=null)im.close();}},h);CameraManager m=(CameraManager)a.getSystemService(Context.CAMERA_SERVICE);m.openCamera(m.getCameraIdList()[0],new CameraDevice.StateCallback(){public void onOpened(CameraDevice c){cam=c;try{CaptureRequest q=c.createCaptureRequest(CameraDevice.TEMPLATE_STILL_CAPTURE);q.addTarget(reader.getSurface());c.createCaptureSession(Collections.singletonList(reader.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession s){try{s.capture(q.build(),null,h);}catch(Exception e){}}public void onConfigureFailed(CameraCaptureSession s){}},h);}catch(Exception e){}}public void onDisconnected(CameraDevice c){c.close();}public void onError(CameraDevice c,int e){c.close();}},h);}catch(Exception e){cb.done(new byte[0]);}}public void close(){try{if(cam!=null)cam.close();if(reader!=null)reader.close();if(t!=null)t.quitSafely();}catch(Exception e){}}}